export type Recipient = {
  id: string
  name: string
  maskedAccount: string
  currency: string
}

export const RECENT_RECIPIENTS: Recipient[] = [
  { id: "r1", name: "Aisha Khan", maskedAccount: "•••• 4821", currency: "EUR" },
  { id: "r2", name: "James Whitfield", maskedAccount: "•••• 1190", currency: "USD" },
  { id: "r3", name: "Priya Raman", maskedAccount: "•••• 7734", currency: "INR" },
  { id: "r4", name: "Lukas Becker", maskedAccount: "•••• 2005", currency: "EUR" },
]

export const SEND_CURRENCY = "GBP"

/** Mock GBP → recipient-currency exchange rates. */
export const EXCHANGE_RATES: Record<string, number> = {
  EUR: 1.17,
  USD: 1.27,
  INR: 106.42,
}

export type SendMoneyData = {
  recipientId: string | null
  recipientSearch: string
  sendAmount: string
  receiveAmount: string
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipientId: null,
  recipientSearch: "",
  sendAmount: "",
  receiveAmount: "",
}

export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const

export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (partial: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (index: number) => void
  reset: () => void
}

export function getRecipient(id: string | null): Recipient | undefined {
  return RECENT_RECIPIENTS.find((r) => r.id === id)
}

export function getRate(currency: string | undefined): number {
  return currency ? (EXCHANGE_RATES[currency] ?? 1) : 1
}

/** Flat 0.5% fee, floored at 1.50 GBP, in GBP. */
export function calcFee(sendAmount: number): number {
  if (!Number.isFinite(sendAmount) || sendAmount <= 0) return 0
  return Math.max(1.5, Math.round(sendAmount * 0.005 * 100) / 100)
}

export function formatMoney(amount: number, currency: string): string {
  if (!Number.isFinite(amount)) return `0.00 ${currency}`
  return `${amount.toFixed(2)} ${currency}`
}

