"use client"

import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RECENT_RECIPIENTS } from "../schema"
import type { SendMoneyStepProps } from "../schema"
import { RecipientRow } from "./_parts"

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const query = data.recipientSearch.trim().toLowerCase()
  const filtered = query
    ? RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(query))
    : RECENT_RECIPIENTS

  const select = (id: string) => {
    patch({ recipientId: id })
    next()
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <div>
        <Label htmlFor="recipient-search" size="sm">
          Search recipients
        </Label>
        <Input
          id="recipient-search"
          size="md"
          variant="default"
          placeholder="Search by name"
          value={data.recipientSearch}
          onChange={(e) => patch({ recipientSearch: e.target.value })}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <span
          style={{
            fontSize: "var(--atlas-font-size-xs)",
            fontWeight: "var(--atlas-font-weight-medium)",
            color: "var(--atlas-foreground-muted)",
            textTransform: "uppercase",
            letterSpacing: "var(--atlas-letter-spacing-wide)",
          }}
        >
          Recent recipients
        </span>
        {filtered.length === 0 && (
          <span style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-foreground-muted)" }}>
            No recipients match &ldquo;{data.recipientSearch}&rdquo;.
          </span>
        )}
        {filtered.map((recipient) => (
          <RecipientRow
            key={recipient.id}
            recipient={recipient}
            selected={data.recipientId === recipient.id}
            onSelect={() => select(recipient.id)}
          />
        ))}
      </div>

      <Button variant="ghost" size="sm" disabled>
        New recipient
      </Button>
    </div>
  )
}

