"use client"

import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { SEND_CURRENCY, calcFee, formatMoney, getRate, getRecipient } from "../schema"
import type { SendMoneyStepProps } from "../schema"

export function Amount({ data, patch, next }: SendMoneyStepProps) {
  const recipient = getRecipient(data.recipientId)
  const rate = getRate(recipient?.currency)
  const currency = recipient?.currency ?? SEND_CURRENCY

  const sendAmount = parseFloat(data.sendAmount)
  const isValid = Number.isFinite(sendAmount) && sendAmount > 0
  const fee = isValid ? calcFee(sendAmount) : 0
  const total = isValid ? sendAmount + fee : 0

  const onSendChange = (value: string) => {
    const parsed = parseFloat(value)
    patch({
      sendAmount: value,
      receiveAmount: Number.isFinite(parsed) && parsed > 0 ? (parsed * rate).toFixed(2) : "",
    })
  }

  const onReceiveChange = (value: string) => {
    const parsed = parseFloat(value)
    patch({
      receiveAmount: value,
      sendAmount: Number.isFinite(parsed) && parsed > 0 ? (parsed / rate).toFixed(2) : "",
    })
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <div>
        <Label htmlFor="send-amount" size="sm">
          You send
        </Label>
        <Input
          id="send-amount"
          size="lg"
          inputMode="decimal"
          placeholder="0.00"
          suffix={SEND_CURRENCY}
          value={data.sendAmount}
          onChange={(e) => onSendChange(e.target.value)}
        />
      </div>

      <div>
        <Label htmlFor="receive-amount" size="sm">
          Recipient gets
        </Label>
        <Input
          id="receive-amount"
          size="lg"
          inputMode="decimal"
          placeholder="0.00"
          suffix={currency}
          value={data.receiveAmount}
          onChange={(e) => onReceiveChange(e.target.value)}
        />
      </div>

      <Card variant="outlined" size="sm">
        <CardContent>
          <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
            <Row label="Fee" value={formatMoney(fee, SEND_CURRENCY)} />
            <Row label="Exchange rate" value={`1 ${SEND_CURRENCY} = ${rate} ${currency}`} />
            <Row label="Total to pay" value={formatMoney(total, SEND_CURRENCY)} emphasize />
          </div>
        </CardContent>
      </Card>

      <Alert
        variant="info"
        size="sm"
        title="Arrives by tomorrow, 5:00 PM"
        description="Delivery time depends on your recipient's bank."
      />

      <Button variant="primary" size="lg" disabled={!isValid} onClick={next}>
        Continue
      </Button>
    </div>
  )
}

function Row({ label, value, emphasize }: { label: string; value: string; emphasize?: boolean }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between" }}>
      <span style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-foreground-muted)" }}>{label}</span>
      <span
        style={{
          fontSize: "var(--atlas-font-size-sm)",
          fontWeight: emphasize ? "var(--atlas-font-weight-semibold)" : "var(--atlas-font-weight-regular)",
        }}
      >
        {value}
      </span>
    </div>
  )
}

